import { fileURLToPath } from 'node:url';
import { readTextFile } from 'jg-fs';

import { SKIP_WAITING_MESSAGE_TYPE } from '../../shared/index.js';
import type { IFirebaseOptions, IServiceWorkerConfig } from '../config/index.js';

// the templates, copied next to the compiled code by the build
const TEMPLATE_URLS = {
  base: new URL('../templates/base.sw.js', import.meta.url),
  'firebase-fcm': new URL('../templates/firebase-fcm.sw.js', import.meta.url),
} as const;

// the first line of every generated worker
const GENERATED_HEADER =
  '// Generated by jg-sw. Changes to this file are overwritten the next time it is generated.';

// what the worker is generated from
export type IRenderServiceWorkerInput = {
  template: IServiceWorkerConfig['template'];
  cacheNamePrefix: string;
  cacheName: string;
  precacheAssets: string[];
  excludeMIMETypes: string[];
  caching: boolean;

  // the precached page that answers a navigation the network can't serve, or null for none
  navigationFallback: string | null;

  // the firebase-fcm template's SDK version and app options
  firebase?: { sdkVersion: string; options: IFirebaseOptions };
};

/**
 * Sets the values of a template's constants, each declared on its own line as
 * `const NAME = <placeholder>;`. Values are serialized as JSON, so strings and paths are escaped.
 * @param template The template's source.
 * @param values The value of each constant, by name.
 * @returns The source with the constants set.
 */
const setConstants = (template: string, values: Record<string, unknown>): string =>
  Object.entries(values).reduce(
    (source, [name, value]) =>
      source.replace(
        new RegExp(`^const ${name} = .*;$`, 'm'),
        // a function, so `$` sequences in the value are never read as replacement patterns
        () => `const ${name} = ${JSON.stringify(value, null, 2)};`,
      ),
    template,
  );

/**
 * Reads one of the worker templates.
 * @param name The template's name.
 * @returns A promise that resolves to the template's source.
 */
const readTemplate = (name: keyof typeof TEMPLATE_URLS): Promise<string> =>
  readTextFile(fileURLToPath(TEMPLATE_URLS[name]));

/**
 * Generates the worker's source from its templates: the base template, followed by the
 * firebase-fcm template when the config selects it.
 * @param input What the worker is generated from.
 * @returns A promise that resolves to the worker's source.
 */
export const renderServiceWorker = async (input: IRenderServiceWorkerInput): Promise<string> => {
  const base = setConstants(await readTemplate('base'), {
    CACHE_NAME_PREFIX: input.cacheNamePrefix,
    CACHE_NAME: input.cacheName,
    PRECACHE_ASSETS: input.precacheAssets,
    EXCLUDE_MIME_TYPES: input.excludeMIMETypes,
    SKIP_WAITING_MESSAGE_TYPE,
    CACHING: input.caching,
    NAVIGATION_FALLBACK: input.navigationFallback,
  });
  if (input.template === 'base' || input.firebase === undefined) {
    return `${GENERATED_HEADER}\n${base}`;
  }
  const firebaseFcm = setConstants(await readTemplate('firebase-fcm'), {
    FIREBASE_SDK_VERSION: input.firebase.sdkVersion,
    FIREBASE_OPTIONS: input.firebase.options,
  });
  return `${GENERATED_HEADER}\n${base.trimEnd()}\n\n${firebaseFcm}`;
};
